RL_Policy::RL_Policy(int history_len, int one_obs_len) {
    one_observation_length = one_obs_len;
    history_length = history_len;
    history_obs_length = one_observation_length * history_length;
    input_history = new float[history_obs_length]();
    normalized_history = new float[history_obs_length]();

    const int num_layers = 4;
    layers = new unsigned int[num_layers]{history_obs_length, 64, 64, 8};
    Actv_Functions = new byte[num_layers-1]{1, 1, 0};

    // action_bias = new float[ACTION_SIZE]{-1.0, -1.0, 0.0, 0.0};
    action_bias = new float[ACTION_SIZE]{0.0, 0.0, 0.0, 0.0};
    action_scale = new float[ACTION_SIZE]{0.25, 0.25, 1.0, 1.0};

#if 0
    NN = (void*)(new NeuralNetwork(layers, weights, biases, num_layers, Actv_Functions));
#endif
    actions_ = new float[ACTION_SIZE]();
}

void RL_Policy::cleanHistory() {
    for(int i = 0; i < history_obs_length; i++) {
        input_history[i] = 0.0;
    }
}

void RL_Policy::updateHistory(const float* new_input) {
    // 1. 左移所有历史记录(跳过第一个observation)
    for(int i = 0; i < (history_length-1)*one_observation_length; i++) {
        input_history[i] = input_history[i + one_observation_length];
    }
    
    // 2. 将新input添加到数组末尾
    int start_pos = (history_length-1)*one_observation_length;
    for(int j = 0; j < one_observation_length; j++) {
        input_history[start_pos + j] = new_input[j];
        // if (j==8) { // debug: 第9个元素是roll, 直接赋值0.0
        //     input_history[start_pos + j] = 0.0;
        // }
    }
}

void RL_Policy::normalizeObservation() {
    for (int i = 0; i < history_obs_length; i++) {
        normalized_history[i] = (input_history[i] - state_mean[i]) / state_std[i];
    }
}

float *RL_Policy::NN_Forward() {
    // 获取各层权重、偏置和大小
    float *weight_ = weights;
    float *bias_ = biases;
    
    // 中间层输出缓冲区
    static float layer_output[64];
    
    // 第一层: layers[0] -> layers[1]
    for(int i=0; i<layers[1]; i++) {
        layer_output[i] = bias_[i];
        for(int j=0; j<layers[0]; j++) {
            layer_output[i] += normalized_history[j] * weight_[i*layers[0] + j];
        }
        // SiLU激活
        layer_output[i] = layer_output[i] / (1 + expf(-layer_output[i]));
    }
    // Serial.println("layer_output 1:" + cvtSensors2String(layer_output, 64, 6));
    
    // 第二层: layers[1] -> layers[2]
    static float layer_output2[64];
    weight_ = weights + layers[0] * layers[1];
    bias_ = biases + layers[1];
    for(int i=0; i<layers[2]; i++) {
        float sum = bias_[i];
        for(int j=0; j<layers[1]; j++) {
            sum += layer_output[j] * weight_[i*layers[1] + j];
        }
        // SiLU激活
        layer_output2[i] = sum / (1 + expf(-sum));
    }
    // Serial.println("layer_output 2:" + cvtSensors2String(layer_output2, 64, 6));
    
    // 输出层: layers[2] -> layers[3]
    weight_ = weights + layers[0] * layers[1] + layers[1] * layers[2];
    bias_ = biases + layers[1] + layers[2];
    for(int i=0; i<layers[3]; i++) {
        nn_output[i] = bias_[i];
        for(int j=0; j<layers[2]; j++) {
            nn_output[i] += layer_output2[j] * weight_[i*layers[2] + j];
        }
        // Tanh激活
        nn_output[i] = tanhf(nn_output[i]);
    }
    
    return nn_output;
}

