String RL_Policy::cvtSensors2String(const float *dataArray, const int arraySize, const int deci) {
    String dataString = "";
    int deci_ = deci;
    for (int i = 0; i < arraySize; i++) {
        deci_ = deci;
        // if (i == 0) deci_ = 0;
        dataString += String(dataArray[i], deci_);
        if (i < arraySize - 1) {
            dataString += ",";
        }
    }
    return dataString;
}

